-- Schema for database: rschema_0351

CREATE TABLE `object` (
  `object_id` varchar(255) NOT NULL,
  `category` varchar(255) NOT NULL,
  PRIMARY KEY (`object_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `user` (
  `user_id` varchar(255) NOT NULL,
  `name` varchar(255) NOT NULL,
  `contact_information` varchar(255) NOT NULL,
  PRIMARY KEY (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `permission_entry` (
  `permission_entry_number` varchar(255) NOT NULL,
  `log_recording_status` varchar(255) NOT NULL,
  `log_path` varchar(255) NOT NULL,
  PRIMARY KEY (`permission_entry_number`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `permission_inheritance` (
  `child_object` varchar(255) NOT NULL,
  `parent_object` varchar(255) NOT NULL,
  PRIMARY KEY (`parent_object`, `child_object`),
  CONSTRAINT `permission_inheritance_ibfk_child_object` FOREIGN KEY (`child_object`) REFERENCES `object` (`object_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `permission_inheritance_ibfk_parent_object` FOREIGN KEY (`parent_object`) REFERENCES `object` (`object_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `authorization` (
  `permission_entry_number` varchar(255) NOT NULL,
  `authorized_object` varchar(255) NOT NULL,
  PRIMARY KEY (`permission_entry_number`, `authorized_object`),
  CONSTRAINT `authorization_ibfk_authorized_object` FOREIGN KEY (`authorized_object`) REFERENCES `object` (`object_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `authorization_ibfk_permission_entry_number` FOREIGN KEY (`permission_entry_number`) REFERENCES `permission_entry` (`permission_entry_number`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `object_assignment` (
  `object_id` varchar(255) NOT NULL,
  `assigned_user` varchar(255) NOT NULL,
  PRIMARY KEY (`object_id`, `assigned_user`),
  CONSTRAINT `object_assignment_ibfk_assigned_user` FOREIGN KEY (`assigned_user`) REFERENCES `user` (`user_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `object_assignment_ibfk_object_id` FOREIGN KEY (`object_id`) REFERENCES `object` (`object_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
